const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const N = data[0];
const L = data.slice(1, 1 + N);

let C = 0;
const P = new Array(N + 1);
P[0] = 0;
for (let i = 0; i < N; i++) {
    C += L[i];
    P[i + 1] = C;
}

if (C % 2 !== 0) {
    console.log('N');
    process.exit(0);
}

const half = C / 2;
const P2 = new Array(2 * N + 1);
for (let i = 0; i <= N; i++) {
    P2[i] = P[i];
}
for (let i = 1; i <= N; i++) {
    P2[N + i] = P[i] + C;
}

let count = 0;
let j = 1;
for (let i = 0; i < N; i++) {
    if (j <= i) j = i + 1;
    while (j <= i + N && P2[j] - P2[i] < half) {
        j++;
    }
    if (j <= i + N && P2[j] - P2[i] === half) {
        count++;
    }
}

console.log(count >= 4 ? 'S' : 'N');
